package dev.smpcristalix.pvpcombat.listener;import dev.smpcristalix.pvpcombat.service.*;import org.bukkit.event.*;import org.bukkit.event.player.*;/** Join applies saved stats; combat logout becomes a death before disconnect. */public final class PlayerLifecycleListener implements Listener{private final StatsService stats;private final CombatService combat;private final PearlService pearls;public PlayerLifecycleListener(StatsService s,CombatService c,PearlService p){stats=s;combat=c;pearls=p;}@EventHandler public void onJoin(PlayerJoinEvent e){stats.apply(e.getPlayer());}@EventHandler public void onQuit(PlayerQuitEvent e){var p=e.getPlayer();if(combat.inCombat(p)&&!p.isDead())p.setHealth(0);combat.clear(p);pearls.reset(p);}}
